// Local, explicit UI translations. No network translator or HTML substitution.
// Bind text nodes and display attributes only; wallet inputs, IDs and action data
// stay untouched. Original text is retained so language changes are reversible.
export const LANGUAGE_KEY='tapemicro-language';
const browserStorage=()=>{
try{return globalThis.localStorage;}catch{return undefined;}};
export function readLanguage(storage=browserStorage()){try{return storage?.getItem(LANGUAGE_KEY)==='en'?'en':'zh';}catch{return'zh';}}
let language=readLanguage();
export const getLanguage=()=>language;
export const locale=()=>language==='en'?'en-US':'zh-CN';
