const escapeRE=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const patterns=templates.map(([source,target])=>{const parts=source.split(/(\{\d+\})/),order=[];return {source,target,order,re:new RegExp('^'+parts.map(part=>/^\{\d+\}$/.test(part)?(order.push(+part.slice(1,-1)),'(.+?)'):escapeRE(part)).join('')+'$')};});
export function translateText(value,lang=language,depth=0){
 const result=translateRaw(value,lang,depth);
 return lang==='en'?result.replace(/(^|[^\d.])1 (miners|listings|transactions|pts)\b/g,(_,prefix,noun)=>prefix+'1 '+({miners:'miner',listings:'listing',transactions:'transaction',pts:'pt'}[noun])):result;
}
function translateRaw(value,lang,depth){
 const text=String(value??'');if(lang!=='en'||!/[\u3400-\u9fff]/.test(text))return text;
 const trimmed=text.trim();if(trimmed.startsWith('✓ '))return text.replace(trimmed,()=> '✓ '+translateText(trimmed.slice(2),lang,depth+1));
 if(trimmed.endsWith('…')===false&&Object.hasOwn(words,trimmed+'…'))return text.replace(trimmed,()=>words[trimmed+'…'].replace(/…$/,''));
 if(Object.hasOwn(words,trimmed))return text.replace(trimmed,()=>words[trimmed]);
 if(depth<5)for(const pattern of patterns){const m=trimmed.match(pattern.re);if(m){const params={};pattern.order.forEach((key,i)=>params[key]=translateText(m[i+1],'en',depth+1));return text.replace(trimmed,()=>pattern.target.replace(/\{(\d+)\}/g,(_,key)=>params[key]));}}
 // These separators join independently rendered messages, not individual words.
 if(depth<5&&/ · |。/.test(trimmed)){const parts=trimmed.split(/( · |。)/);const translated=parts.map(part=>part==='。'?'. ':part===' · '?part:translateText(part,'en',depth+1)).join('');if(!/[\u3400-\u9fff]/.test(translated))return text.replace(trimmed,()=>translated.trimEnd());}
 return text;
}
const textBindings=new WeakMap(),attributeBindings=new WeakMap();
function bindText(node){const current=node.nodeValue,previous=textBindings.get(node),override=node.parentElement?.getAttribute('data-i18n-en');if(previous?.language===language&&current===previous.last&&override===previous.override)return;const source=previous&&current===previous.last?previous.source:current;const next=language==='en'&&override||translateText(source);if(next!==current)node.nodeValue=next;textBindings.set(node,{source,last:next,language,override});}
export function localizeTree(root=globalThis.document?.body){
 if(!root)return;const doc=root.ownerDocument??root;
 const walker=doc.createTreeWalker(root,4);let node;
 while(node=walker.nextNode())if(!node.parentElement?.closest('script,style,textarea,pre,code,[data-no-i18n],[data-rk]')&&node.nodeValue.trim())bindText(node);
 const attrs=['placeholder','aria-label','title','data-label'];const elements=[...(root.nodeType===1?[root]:[]),...root.querySelectorAll('[placeholder],[aria-label],[title],[data-label]')];
 for(const el of elements){if(el.closest('[data-no-i18n],[data-rk]'))continue;const record=attributeBindings.get(el)??{};for(const attr of attrs){if(!el.hasAttribute(attr))continue;const current=el.getAttribute(attr),previous=record[attr];if(previous?.language===language&&current===previous.last)continue;const source=previous&&current===previous.last?previous.source:current,next=translateText(source);if(current!==next)el.setAttribute(attr,next);record[attr]={source,last:next,language};}attributeBindings.set(el,record);}
}
export function setLanguage(next,{storage=browserStorage()}={}){
 language=next==='en'?'en':'zh';try{storage?.setItem(LANGUAGE_KEY,language);}catch{}return language;
}
export function initializeLocalization({onChange=()=>{}}={}){
 const doc=globalThis.document;if(!doc)return;
 const title=doc.title,description=doc.querySelector('meta[name="description"]'),descriptionSource=description?.content;
 const button=doc.getElementById('language-switch');
 const apply=()=>{doc.documentElement.lang=language==='en'?'en':'zh-CN';doc.title=translateText(title);if(description)description.content=translateText(descriptionSource);localizeTree(doc.body);for(const link of doc.querySelectorAll('[data-guide-link]'))link.setAttribute('href',link.getAttribute('data-guide-link').replace(/guide(?:-en)?\.html$/,language==='en'?'guide-en.html':'guide.html'));if(button){button.textContent=language==='en'?'中文':'EN';button.setAttribute('aria-label',language==='en'?'Switch to Chinese':'切换到英文');button.title=language==='en'?'Switch to Chinese':'切换到英文';}};
 button?.addEventListener('click',event=>{event.stopPropagation();setLanguage(language==='en'?'zh':'en');apply();onChange();});
 apply();return{apply};
}
